import java.util.*;

class Solution {
    public int binarySearch(int[] nums, int target) {
        return search(nums, target, 0);
    }

    private int search(int[] nums, int target, int index) {
        if (index >= nums.length) {
            return -1;
        }
        if (nums[index] == target) {
            return index;
        }
        return search(nums, target, index + 1);
    }
}
